import express from 'express'
import { writeReview, readReviews } from './routes/reviews'
import { account } from './routes/account'
const app = express()
app.get('/account', account())
app.get('/reviews', readReviews())
app.put('/reviews', writeReview())

import { Collection } from 'marsdb'
export const reviewsCollection = new Collection('reviews')

export class AccountService {
 current() { return this.http.get('/account') }
}

export class ReviewsService {
 create(review) { return this.http.put('/reviews', review) }
}

export class ReviewsComponent {
 reviews = inject(ReviewsService)
 accounts = inject(AccountService)
 init() { this.accounts.current().subscribe((account) => { this.author.set(account.email) }) }
 submit() { const review = { author: this.author(), message: this.message }; this.reviews.create(review) }
}

import { Model, DataTypes } from 'sequelize'
class UserModel extends Model {}
UserModel.init({email: {type: DataTypes.STRING}}, {modelName: 'User'})

export function account() { return (req, res) => { const principal = security.authenticatedUsers.get(req); res.json({ email: principal.email }) } }

import { reviewsCollection } from '../data/db'
export function writeReview() { return (req, res) => { reviewsCollection.insert({ author: req.body.author, message: req.body.message }); res.json({ok: true}) } }
export function readReviews() { return (req, res) => { reviewsCollection.find({}).then((records) => { res.json(records) }) } }

